// "Investment Video Breakdowns" content library — hand-picked subtitle summaries of YouTube investment videos.
// Workflow: get the video subtitles → use Claude to summarize into the structure below → insert an entry at the "beginning" of the VID_NOTES array → deploy to go live.
// When there are no entries, the frontend automatically hides this section. Entries are shown in array order, newest first.

export interface VidNote {
  id: string;         // Unique slug, e.g. "2026-06-veteran-on-nvda"
  title: string;      // Breakdown title (write your own, summarizing the video's core thesis)
  channel: string;    // YouTube channel name
  videoTitle: string; // Original video title
  url: string;        // Video link
  date: string;       // Video publish date YYYY-MM-DD
  takeaways: string[];// Key takeaways (3~6 items, one sentence each)
  summary: string;    // Detailed summary (several paragraphs, separated by \n)
  tickers?: string[]; // Stock tickers involved, e.g. ["NVDA","TSM"]
  segs?: string[];    // Related supply-chain segment keys (see taxonomy.ts); the map page uses these to auto-attach notes under the corresponding segment
  category?: "invest" | "howto"; // Category: invest=investment views (default) | howto=AI hands-on/tool tutorials
}

